//! Actual marketplace Δ preserves hidden stable bid IDs and original Vec rank.
use super::*;
use super::{original_rows::OriginalProjectionRowDataV1,state_columns::OriginalStateColumnsDataV1,market_rows::OriginalMarketRecordDataV1,market_index::ProjectionBidIndexDataV1};
use oasis7_world_state::{incremental_owner_closure::{CurrentMarketplaceProjectionDeltaV1,MarketplaceProjectionPatchRefV1 as Patch},incremental_module_marketplace::ModuleMarketplaceFieldV1 as Kind};
use oasis7_formal_protocol::{incremental_execution::{ExecutionTransaction,ExecutionFence},incremental_state::MerkleNodeReader};
use std::cell::RefCell;
fn copy(v:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<ReservedValue<Vec<u8>>,BodyMutationError>{super::electricity::bytes(v,common)}
trait MarketRowsV1{
 fn market_rows_v1(&self,kind:Kind,common:&mut FormalBoundedContextV1<'_>)->Result<&super::original_rows::OriginalProjectionRowsDataV1,BodyMutationError>;
 fn replace_market_rows_v1(&mut self,kind:Kind,rows:super::original_rows::OriginalProjectionRowsDataV1,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>;
}
impl MarketRowsV1 for OriginalStateColumnsDataV1{
 fn market_rows_v1(&self,kind:Kind,common:&mut FormalBoundedContextV1<'_>)->Result<&super::original_rows::OriginalProjectionRowsDataV1,BodyMutationError>{self.map_data_v1(kind.name(),common)?.map(AsRef::as_ref).ok_or_else(||invalid("marketplace actual map missing"))}
 fn replace_market_rows_v1(&mut self,kind:Kind,rows:super::original_rows::OriginalProjectionRowsDataV1,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{self.replace_original_map_data_v1(kind.name(),rows,common)}
}
pub(super) fn fold_market_v1<M:MerkleNodeReader>(out:&mut OriginalStateColumnsDataV1,source:&CurrentMarketplaceProjectionDeltaV1,tx:&ExecutionTransaction<'_,M>,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<(),BodyMutationError>{fold_rows_v1(out,source,tx,common,live)}
fn fold_rows_v1<M:MerkleNodeReader,T:MarketRowsV1>(out:&mut T,source:&CurrentMarketplaceProjectionDeltaV1,tx:&ExecutionTransaction<'_,M>,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<(),BodyMutationError>{source.validate(tx,common.memory(),live)?;let common=RefCell::new(common);
 source.visit_entities_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,key,before,after,meta|{let mut common=common.borrow_mut();let rows=out.market_rows_v1(kind,&mut common)?;let old=rows.row_data_v1(semantic,&mut common)?;if old.is_some()!=before{return Err(invalid("marketplace actual before presence"))}
 let rows=if !after{rows.without_row_data_v1(semantic,&mut common)?}else if kind==Kind::ArtifactBids{let meta=meta.ok_or_else(||invalid("actual marketplace index metadata missing"))?;let value=match old{Some(row)=>row.market_bids_v1().ok_or_else(||invalid("marketplace resident index kind"))?.with_actual_meta_v1(meta,&mut common)?,None=>ProjectionBidIndexDataV1::empty_for_new_v1(meta,&mut common)?};let row=OriginalProjectionRowDataV1::from_market_bids_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?;rows.with_row_data_v1(row,&mut common)?}else if before{if old.and_then(|r|r.market_record_v1()).is_none(){return Err(invalid("marketplace resident fixed record kind"))}return Ok(())}else{let value=OriginalMarketRecordDataV1::empty_for_new_v1(kind,&mut common)?;let row=OriginalProjectionRowDataV1::from_market_record_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?;rows.with_row_data_v1(row,&mut common)?};out.replace_market_rows_v1(kind,rows,&mut common)})?;
 // Index identities/presence precede payload updates independently of their
 // physical member-key order. This does not reorder the logical Vec.
 source.visit_patches_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,key,path|{let Patch::Node(id,after)=path else{return Ok(())};if kind!=Kind::ArtifactBids{return Err(invalid("marketplace node field binding"))}let mut common=common.borrow_mut();let rows=out.market_rows_v1(kind,&mut common)?;let value=rows.row_data_v1(semantic,&mut common)?.and_then(|r|r.market_bids_v1()).ok_or_else(||invalid("marketplace index current record missing"))?.with_actual_node_v1(id,after,&mut common)?;let row=OriginalProjectionRowDataV1::from_market_bids_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?;let rows=rows.with_row_data_v1(row,&mut common)?;out.replace_market_rows_v1(kind,rows,&mut common)})?;
 source.visit_patches_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,key,path|{let mut common=common.borrow_mut();let rows=out.market_rows_v1(kind,&mut common)?;let old=rows.row_data_v1(semantic,&mut common)?.ok_or_else(||invalid("marketplace payload current record missing"))?;let row=match path{Patch::Node(_,_)=>return Ok(()),Patch::Bid(id,name,value)=>{if kind!=Kind::ArtifactBids{return Err(invalid("marketplace bid field binding"))}let value=old.market_bids_v1().ok_or_else(||invalid("marketplace index DATA kind"))?.with_actual_bid_field_v1(id,name,value,&mut common)?;OriginalProjectionRowDataV1::from_market_bids_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?},Patch::Scalar(name,value)=>{if kind==Kind::ArtifactBids{return Err(invalid("marketplace scalar field binding"))}let value=old.market_record_v1().ok_or_else(||invalid("marketplace fixed DATA kind"))?.with_actual_patch_v1(name,value,&mut common)?;OriginalProjectionRowDataV1::from_market_record_data_v1(copy(semantic,&mut common)?,copy(key,&mut common)?,value,&mut common)?}};let rows=rows.with_row_data_v1(row,&mut common)?;out.replace_market_rows_v1(kind,rows,&mut common)})?;
 source.visit_entities_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,_key,_before,after,_meta|{if !after{return Ok(())}let mut common=common.borrow_mut();let rows=out.market_rows_v1(kind,&mut common)?;let record=rows.row_data_v1(semantic,&mut common)?.ok_or_else(||invalid("marketplace final record missing"))?;if kind==Kind::ArtifactBids{record.market_bids_v1().ok_or_else(||invalid("marketplace final index kind"))?.validate_complete_v1(&mut common)}else{record.market_record_v1().ok_or_else(||invalid("marketplace final fixed kind"))?.validate_complete_v1(&mut common)}})?;
 source.visit_patches_with_work_v1(|s,b|common.borrow_mut().charge(s,b).map_err(paid),|kind,semantic,_key,path|{let id=match path{Patch::Node(id,_)|Patch::Bid(id,_,_)=>id,Patch::Scalar(_,_)=>return Ok(())};let mut common=common.borrow_mut();let rows=out.market_rows_v1(kind,&mut common)?;rows.row_data_v1(semantic,&mut common)?.and_then(|r|r.market_bids_v1()).ok_or_else(||invalid("marketplace final index source"))?.validate_actual_bid_v1(id,&mut common)})?;
 let common=common.into_inner();source.validate(tx,common.memory(),live)
}

pub(super) struct QualifiedMarketplaceColumnDataV1{rows:[super::original_rows::OriginalProjectionRowsDataV1;3],_fee:MemoryReservation}
fn slot(kind:Kind)->usize{match kind{Kind::VisualEntities=>0,Kind::ArtifactListings=>1,Kind::ArtifactBids=>2}}
impl MarketRowsV1 for QualifiedMarketplaceColumnDataV1{
 fn market_rows_v1(&self,kind:Kind,common:&mut FormalBoundedContextV1<'_>)->Result<&super::original_rows::OriginalProjectionRowsDataV1,BodyMutationError>{common.consume_steps(1).map_err(paid)?;let rows=&self.rows[slot(kind)];rows.validate(common)?;Ok(rows)}
 fn replace_market_rows_v1(&mut self,kind:Kind,rows:super::original_rows::OriginalProjectionRowsDataV1,common:&mut FormalBoundedContextV1<'_>)->Result<(),BodyMutationError>{rows.validate(common)?;common.consume_steps(1).map_err(paid)?;self.rows[slot(kind)]=rows;Ok(())}
}
impl QualifiedMarketplaceColumnDataV1{
 pub(super) fn from_actual_qualified_v1<M:MerkleNodeReader>(source:&oasis7_world_state::incremental_owner_closure::QualifiedMarketplaceProjectionColumnsV1,tx:&ExecutionTransaction<'_,M>,common:&mut FormalBoundedContextV1<'_>,live:&ExecutionFence)->Result<Self,BodyMutationError>{source.validate(tx,common.memory(),live)?;let n=std::mem::size_of::<Self>();common.charge(1,n as u64).map_err(paid)?;let fee=common.memory().reserve(n,MemoryClass::Ordinary).map_err(ValueTreeError::Memory)?;use super::original_rows::OriginalProjectionRowsDataV1 as Rows;let mut out=Self{rows:[Rows::empty_data_v1(common)?,Rows::empty_data_v1(common)?,Rows::empty_data_v1(common)?],_fee:fee};fold_rows_v1(&mut out,source.projection_data_v1(),tx,common,live)?;source.validate(tx,common.memory(),live)?;Ok(out)}
 pub(super) fn rows_v1(&self,kind:Kind,common:&mut FormalBoundedContextV1<'_>)->Result<&super::original_rows::OriginalProjectionRowsDataV1,BodyMutationError>{if !self._fee.uses_budget(common.memory()){return Err(invalid("qualified marketplace columns pool"))}self.market_rows_v1(kind,common)}
}
